1	package cli
2	
3	import (
4		"encoding/binary"
5		"errors"
6		"fmt"
7		"math"
8		"strings"
9		"sync"
10		"unicode"
11	
12		entirebrain "github.com/ashtom/entire-brain"
13	)
14	
15	// Embedder turns text into a unit-length vector for semantic recall. It is the
16	// Phase D abstraction boundary: the bundled backend is a pure-Go Model2Vec
17	// static model (staticEmbedder), but a transformer bi-encoder (ONNX) or a
18	// provider-shelled embedder can drop in behind this interface without touching
19	// the ranking path, once the eval harness shows the static model leaves recall
20	// headroom. Embed returns a slice of length Dim(); for empty/all-unknown input
21	// it returns the zero vector (callers treat a zero vector as "no signal").
22	type Embedder interface {
23		Embed(text string) []float32
24		Dim() int
25		// ID identifies the model + revision, used to invalidate cached fact
26		// vectors when the backend changes.
27		ID() string
28	}
29	
30	// staticEmbedder is a Model2Vec static embedding table: tokenize (BERT
31	// WordPiece) -> gather per-token vectors -> mean-pool -> L2-normalize. The
32	// matrix is int8 per-column quantized; rows are dequantized on gather, which
33	// keeps only ~the int8 table resident and is cheap since each text touches only
34	// a handful of tokens.
35	type staticEmbedder struct {
36		id      string
37		dim     int
38		vocab   map[string]int32
39		matrix  []int8    // vocab*dim, row-major
40		scales  []float32 // len dim, per-column dequant scale
41		unkID   int32
42		cont    string // WordPiece continuation prefix, e.g. "##"
43		lower   bool
44		strip   bool
45		chinese bool
46	}
47	
48	const embedModelMagic = "EBM1"
49	
50	// maxWordPieceChars matches BERT's max_input_chars_per_word: a token longer
51	// than this is emitted as [UNK] rather than greedily decomposed.
52	const maxWordPieceChars = 100
53	
54	func loadStaticEmbedder(raw []byte) (*staticEmbedder, error) {
55		r := &byteReader{b: raw}
56		if string(r.take(4)) != embedModelMagic {
57			return nil, errors.New("embed model: bad magic")
58		}
59		if v := r.u32(); v != 1 {
60			return nil, fmt.Errorf("embed model: unsupported version %d", v)
61		}
62		id := string(r.take(int(r.u16())))
63		dim := int(r.u32())
64		vocabSize := int(r.u32())
65		if dtype := r.u32(); dtype != 1 {
66			return nil, fmt.Errorf("embed model: unsupported dtype %d", dtype)
67		}
68		flags := r.u32()
69		unkID := int32(r.u32())
70		cont := string(r.take(int(r.u16())))
71		if r.err != nil {
72			return nil, fmt.Errorf("embed model header: %w", r.err)
73		}
74		if dim <= 0 || vocabSize <= 0 {
75			return nil, errors.New("embed model: empty dim/vocab")
76		}
77		vocab := make(map[string]int32, vocabSize)
78		for i := 0; i < vocabSize; i++ {
79			tok := string(r.take(int(r.u16())))
80			if r.err != nil {
81				return nil, fmt.Errorf("embed model vocab[%d]: %w", i, r.err)
82			}
83			vocab[tok] = int32(i)
84		}
85		scales := make([]float32, dim)
86		for i := range scales {
87			scales[i] = math.Float32frombits(r.u32())
88		}
89		matrix := make([]int8, vocabSize*dim)
90		mb := r.take(len(matrix))
91		if r.err != nil {
92			return nil, fmt.Errorf("embed model matrix: %w", r.err)
93		}
94		for i, b := range mb {
95			matrix[i] = int8(b)
96		}
97		return &staticEmbedder{
98			id: id, dim: dim, vocab: vocab, matrix: matrix, scales: scales,
99			unkID: unkID, cont: cont,
100			lower:   flags&1 != 0,
101			strip:   flags&2 != 0,
102			chinese: flags&4 != 0,
103		}, nil
104	}
105	
106	func (e *staticEmbedder) Dim() int   { return e.dim }
107	func (e *staticEmbedder) ID() string { return e.id }
108	
109	func (e *staticEmbedder) Embed(text string) []float32 {
110		out := make([]float32, e.dim)
111		ids := e.tokenize(text)
112		if len(ids) == 0 {
113			return out
114		}
115		for _, id := range ids {
116			base := int(id) * e.dim
117			row := e.matrix[base : base+e.dim]
118			for d := 0; d < e.dim; d++ {
119				out[d] += float32(row[d]) * e.scales[d]
120			}
121		}
122		inv := 1.0 / float32(len(ids))
123		var norm float64
124		for d := range out {
125			out[d] *= inv
126			norm += float64(out[d]) * float64(out[d])
127		}
128		if norm > 0 {
129			s := float32(1.0 / math.Sqrt(norm))
130			for d := range out {
131				out[d] *= s
132			}
133		}
134		return out
135	}
136	
137	// tokenize replicates BERT BertNormalizer + BertPreTokenizer + WordPiece so the
138	// gathered token ids match the ids the model was distilled against (validated
139	// by the golden-parity test).
140	func (e *staticEmbedder) tokenize(text string) []int32 {
141		var ids []int32
142		for _, word := range e.preTokenize(e.normalize(text)) {
143			ids = e.wordPiece(word, ids)
144		}
145		return ids
146	}
147	
148	// normalize applies clean_text, handle_chinese_chars, lowercase, and accent
149	// stripping. Accent stripping folds Latin precomposed letters to their base
150	// (covering the realistic English-plus-names corpus) rather than pulling in a
151	// full Unicode NFD dependency.
152	func (e *staticEmbedder) normalize(text string) string {
153		var b strings.Builder
154		b.Grow(len(text))
155		for _, r := range text {
156			if r == 0 || r == 0xFFFD || (unicode.IsControl(r) && r != '\t' && r != '\n' && r != '\r') {
157				continue // clean_text: drop nulls and control chars
158			}
159			if unicode.IsSpace(r) {
160				b.WriteByte(' ')
161				continue
162			}
163			if e.chinese && isCJK(r) {
164				b.WriteByte(' ')
165				b.WriteRune(r)
166				b.WriteByte(' ')
167				continue
168			}
169			if e.lower {
170				r = unicode.ToLower(r)
171			}
172			if e.strip {
173				if folded, ok := stripAccent(r); ok {
174					if folded != 0 {
175						b.WriteRune(folded)
176					}
177					continue
178				}
179			}
180			b.WriteRune(r)
181		}
182		return b.String()
183	}
184	
185	// preTokenize splits on whitespace and isolates punctuation into its own
186	// tokens, matching BertPreTokenizer.
187	func (e *staticEmbedder) preTokenize(text string) []string {
188		var out []string
189		for _, field := range strings.Fields(text) {
190			var cur strings.Builder
191			for _, r := range field {
192				if isBertPunct(r) {
193					if cur.Len() > 0 {
194						out = append(out, cur.String())
195						cur.Reset()
196					}
197					out = append(out, string(r))
198					continue
199				}
200				cur.WriteRune(r)
201			}
202			if cur.Len() > 0 {
203				out = append(out, cur.String())
204			}
205		}
206		return out
207	}
208	
209	// wordPiece greedily decomposes one word into the longest matching vocab
210	// pieces (continuation pieces carry the cont prefix), appending their ids. A
211	// word that cannot be fully covered contributes a single [UNK].
212	func (e *staticEmbedder) wordPiece(word string, ids []int32) []int32 {
213		runes := []rune(word)
214		if len(runes) == 0 {
215			return ids
216		}
217		if len(runes) > maxWordPieceChars {
218			return append(ids, e.unkID)
219		}
220		start := 0
221		var pieces []int32
222		for start < len(runes) {
223			end := len(runes)
224			found := int32(-1)
225			for start < end {
226				sub := string(runes[start:end])
227				if start > 0 {
228					sub = e.cont + sub
229				}
230				if id, ok := e.vocab[sub]; ok {
231					found = id
232					break
233				}
234				end--
235			}
236			if found < 0 {
237				return append(ids, e.unkID) // whole word is [UNK]
238			}
239			pieces = append(pieces, found)
240			start = end
241		}
242		return append(ids, pieces...)
243	}
244	
245	func isCJK(r rune) bool {
246		return (r >= 0x4E00 && r <= 0x9FFF) || (r >= 0x3400 && r <= 0x4DBF) ||
247			(r >= 0x20000 && r <= 0x2A6DF) || (r >= 0xF900 && r <= 0xFAFF)
248	}
249	
250	// isBertPunct matches BERT's punctuation set: the ASCII punctuation ranges plus
251	// any Unicode punctuation category.
252	func isBertPunct(r rune) bool {
253		if (r >= '!' && r <= '/') || (r >= ':' && r <= '@') || (r >= '[' && r <= '`') || (r >= '{' && r <= '~') {
254			return true
255		}
256		return unicode.IsPunct(r)
257	}
258	
259	// defaultEmbedder lazily loads the bundled static model once. A load failure
260	// (corrupt/absent asset) yields nil so semantic recall degrades to the lexical
261	// path rather than failing — embeddings are optional by design.
262	var (
263		defaultEmbedderOnce sync.Once
264		defaultEmbedderInst Embedder
265	)
266	
267	func defaultEmbedder() Embedder {
268		defaultEmbedderOnce.Do(func() {
269			e, err := loadStaticEmbedder(entirebrain.EmbedModel)
270			if err == nil {
271				defaultEmbedderInst = e
272			}
273		})
274		return defaultEmbedderInst
275	}
276	
277	// byteReader is a tiny sticky-error reader for the fixed model layout.
278	type byteReader struct {
279		b   []byte
280		off int
281		err error
282	}
283	
284	func (r *byteReader) take(n int) []byte {
285		if r.err != nil {
286			return nil
287		}
288		if n < 0 || r.off+n > len(r.b) {
289			r.err = errors.New("unexpected end of data")
290			return nil
291		}
292		s := r.b[r.off : r.off+n]
293		r.off += n
294		return s
295	}
296	
297	func (r *byteReader) u16() uint16 {
298		b := r.take(2)
299		if b == nil {
300			return 0
301		}
302		return binary.LittleEndian.Uint16(b)
303	}
304	
305	func (r *byteReader) u32() uint32 {
306		b := r.take(4)
307		if b == nil {
308			return 0
309		}
310		return binary.LittleEndian.Uint32(b)
311	}
