1	package cli
2	
3	import (
4		"math"
5		"sort"
6	)
7	
8	// rrfK is the Reciprocal Rank Fusion constant. 60 is the canonical value from
9	// the original RRF paper and what hybrid-search systems (e.g. qmd) use; it
10	// damps the influence of a single retriever's top ranks so neither the lexical
11	// nor the semantic list can unilaterally dominate the fusion.
12	const rrfK = 60.0
13	
14	// semanticReranker holds the embedder and a cache of fact vectors. Fact ids are
15	// content-derived, so a vector is valid for the life of the fact: the in-memory
16	// cache makes an eval over many queries embed each fact at most once, and an
17	// optional disk store (recall/brief) carries vectors across CLI invocations.
18	type semanticReranker struct {
19		e       Embedder
20		cache   map[string][]float32
21		store   *embedStore     // nil => in-memory only (eval, tests)
22		touched map[string]bool // ids seen this run; nil unless disk-backed
23		dirty   bool            // a new vector was embedded this run
24	}
25	
26	// newSemanticReranker returns nil when no embedder is available, so callers can
27	// pass the result straight to rankFactsFused and get the pure-lexical path.
28	// This variant is in-memory only — used by eval and tests, which should not
29	// read or write a persistent cache.
30	func newSemanticReranker(e Embedder) *semanticReranker {
31		if e == nil {
32			return nil
33		}
34		return &semanticReranker{e: e, cache: map[string][]float32{}}
35	}
36	
37	// newSemanticRerankerForBranch adds a disk-backed vector cache under
38	// facts/<branch>/embeddings/ so recall and brief reuse vectors across
39	// invocations instead of re-embedding the branch each time.
40	func newSemanticRerankerForBranch(e Embedder, brainDir, branch string) *semanticReranker {
41		rr := newSemanticReranker(e)
42		if rr == nil {
43			return nil
44		}
45		rr.store = newEmbedStore(brainDir, branch, e.ID(), e.Dim())
46		rr.cache = rr.store.load()
47		rr.touched = map[string]bool{}
48		return rr
49	}
50	
51	func (s *semanticReranker) factVector(f factRecord) []float32 {
52		if s.touched != nil {
53			s.touched[f.ID] = true
54		}
55		if v, ok := s.cache[f.ID]; ok {
